pragma solidity 0.8.26;
pragma experimental ABIEncoderV2;

import "forge-std/Test.sol";
import "../src/0xec329ffc97d75fe03428ae155fc7793431487f63.sol";

contract EthRejector {
    fallback() external payable {
        revert("ETH not accepted");
    }
}

contract TokenSenderTest is Test {
    TokenSender tokenSender;
    address owner = address(0x1);
    address attacker = address(0x2);
    address mockToken = address(0x3);

    function setUp() public {
        vm.prank(owner);
        tokenSender = new TokenSender(mockToken);
    }

    function testUncheckedCallVulnerability() public {
        // Deploy a contract that will reject ETH transfers
        EthRejector rejector = new EthRejector();

        // Send some ETH to the TokenSender contract first
        vm.deal(address(tokenSender), 1 ether);

        // Record initial ETH balance of TokenSender
        uint256 initialBalance = address(tokenSender).balance;

        // Attempt to send ETH to the rejecting contract
        bytes memory data = abi.encodeWithSignature("fakeFunction()");
        vm.prank(owner);
        tokenSender.execute(address(rejector), 0.5 ether, data);

        // Check if the ETH was actually deducted despite the failed transfer
        uint256 finalBalance = address(tokenSender).balance;

        // This assertion will fail because the execute() function doesn't check the call return value
        assertEq(finalBalance, initialBalance, "ETH balance should remain unchanged after failed transfer");
    }

    function testSuccessfulCall() public {
        // Send some ETH to the TokenSender contract first
        vm.deal(address(tokenSender), 1 ether);

        // Record initial ETH balance of TokenSender
        uint256 initialBalance = address(tokenSender).balance;

        // Create a payable address that will accept ETH
        address payable receiver = payable(address(0x4));

        // Attempt to send ETH successfully
        bytes memory data = abi.encodeWithSignature("fakeFunction()");
        vm.prank(owner);
        tokenSender.execute(receiver, 0.5 ether, data);

        // Check if the ETH was transferred correctly
        uint256 finalBalance = address(tokenSender).balance;

        assertEq(finalBalance, initialBalance - 0.5 ether, "ETH balance should be reduced after successful transfer");
        assertEq(receiver.balance, 0.5 ether, "Receiver should have received ETH");
    }
}
